import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
} from "@/components/ui/card";
import { trpc } from "@/utils/trpc";
import { useQuery } from "@tanstack/react-query";
import { Link } from "@tanstack/react-router";
import {
  Eye,
  Receipt,
} from "lucide-react";
import dayjs from "dayjs";
import { Pagination } from "./pagination";

interface TransaksiTabProps {
  page: number;
  limit: number;
  onPageChange: (page: number) => void;
}

const ORDER_STATUS_CONFIG: Record<
  string,
  { label: string; className: string }
> = {
  pending: {
    label: "Menunggu Pembayaran",
    className: "bg-amber-50 text-amber-700 hover:bg-amber-100",
  },
  waiting_verification: {
    label: "Menunggu Verifikasi",
    className: "bg-blue-50 text-blue-700 hover:bg-blue-100",
  },
  verified: {
    label: "Selesai",
    className: "bg-emerald-50 text-emerald-700 hover:bg-emerald-100",
  },
  cancelled: {
    label: "Dibatalkan",
    className: "bg-rose-50 text-rose-700 hover:bg-rose-100",
  },
  expired: {
    label: "Kadaluarsa",
    className: "bg-rose-50 text-rose-700 hover:bg-rose-100",
  },
};

export function TransaksiTab({ page, limit, onPageChange }: TransaksiTabProps) {
  const { data, isLoading } = useQuery(
    trpc.pelatihan.order.getUserOrdersPaginated.queryOptions({
      page,
      limit,
    }),
  );

  if (isLoading) {
    return (
      <div className="space-y-4">
        {[1, 2].map((i) => (
          <Card
            key={i}
            className="animate-pulse border-slate-100 p-6 shadow-sm"
          >
            <div className="mb-4 h-6 w-1/3 rounded bg-slate-100" />
            <div className="mb-2 h-4 w-1/2 rounded bg-slate-100" />
          </Card>
        ))}
      </div>
    );
  }

  const orders = data?.data ?? [];
  const totalPages = data?.pagination?.totalPages ?? 0;

  if (orders.length === 0) {
    return (
      <div className="flex h-64 flex-col items-center justify-center rounded-2xl border border-dashed border-slate-200 bg-white p-6 text-center">
        <div className="mb-4 rounded-full bg-blue-50 p-4">
          <Receipt className="h-6 w-6 text-[#1061D6]" />
        </div>
        <p className="font-['Plus_Jakarta_Sans'] text-sm font-bold text-slate-800">
          Belum ada transaksi
        </p>
        <p className="mb-6 max-w-sm font-['Poppins'] text-xs text-slate-500">
          Anda belum melakukan pemesanan kelas pelatihan.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="overflow-x-auto rounded-2xl border border-slate-100 bg-white shadow-sm">
        <table className="w-full border-collapse text-left font-['Poppins'] text-xs">
          <thead>
            <tr className="border-b border-slate-100 bg-slate-50/50 font-bold text-slate-400">
              <th className="px-6 py-4 font-semibold">Nomor Transaksi</th>
              <th className="px-6 py-4 font-semibold">Pelatihan</th>
              <th className="px-6 py-4 font-semibold">Tanggal Pembuatan</th>
              <th className="px-6 py-4 font-semibold">Total Pembayaran</th>
              <th className="px-6 py-4 font-semibold">Status</th>
              <th className="px-6 py-4 text-center font-semibold">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 text-slate-600">
            {orders.map((order) => {
              const status = ORDER_STATUS_CONFIG[order.status] ?? {
                label: order.status,
                className: "bg-slate-100 text-slate-700",
              };

              return (
                <tr key={order.id} className="hover:bg-slate-50/50">
                  <td className="px-6 py-4 font-mono font-bold text-slate-800">
                    {order.orderNumber}
                  </td>
                  <td className="max-w-[200px] px-6 py-4">
                    <div className="flex flex-col gap-0.5">
                      {order.items.map((item: any) => (
                        <span
                          key={item.id}
                          className="truncate font-semibold text-slate-700"
                        >
                          {item.pelatihan?.title}
                        </span>
                      ))}
                    </div>
                  </td>
                  <td className="px-6 py-4 font-medium text-slate-400">
                    {dayjs(order.createdAt).format("DD MMM YYYY, HH:mm")}
                  </td>
                  <td className="px-6 py-4 font-bold text-slate-700">
                    Rp {order.totalAmount.toLocaleString("id-ID")}
                  </td>
                  <td className="px-6 py-4">
                    <Badge
                      className={`rounded-lg border-none text-[10px] font-bold uppercase shadow-none ${status.className}`}
                    >
                      {status.label}
                    </Badge>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <Button
                      variant="outline"
                      size="sm"
                      className="rounded-xl border-slate-200 font-bold text-slate-700"
                      asChild
                    >
                      <Link
                        to="/pelatihan/transaksi/$orderId"
                        params={{ orderId: order.id }}
                      >
                        <Eye className="mr-1 h-3.5 w-3.5" />
                        Detail
                      </Link>
                    </Button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <Pagination
        currentPage={page}
        totalPages={totalPages}
        onPageChange={onPageChange}
      />
    </div>
  );
}

